<template><ForgeDialog title="Wi-Fi QR code" description="Generate a QR code that can connect a phone or laptop to your wireless network." eyebrow="WORKSPACE / NETWORK" @close="emit('close')"><div class="wifi-panel"><label>Network name (SSID)<input v-model="ssid" placeholder="Office Wi-Fi" /></label><label>Password<input v-model="password" type="password" placeholder="Wireless password" /></label><label>Security<select v-model="security"><option value="WPA">WPA / WPA2 / WPA3</option><option value="WEP">WEP</option><option value="nopass">No password</option></select></label><label v-if="security==='WPA'">Hidden network<input v-model="hidden" type="checkbox" /></label><div class="wifi-preview"><img v-if="image" :src="image" alt="Wi-Fi QR code" /><span v-else>Enter network details</span></div><button class="primary-button" :disabled="!image" @click="download">Download PNG</button><p class="website-help">The QR payload is generated locally. Passwords are not stored.</p></div></ForgeDialog></template>
<script setup lang="ts">
import { ref, watch } from 'vue'
import QRCode from 'qrcode'
import ForgeDialog from './ForgeDialog.vue'
const emit=defineEmits<{close:[]}>(); const ssid=ref(''); const password=ref(''); const security=ref<'WPA'|'WEP'|'nopass'>('WPA'); const hidden=ref(false); const image=ref(''); let timer:number|undefined; const payload=()=> 'WIFI:T:'+security.value+';S:'+ssid.value.replace(/[\\;,:]/g,'\\$&')+';P:'+password.value.replace(/[\\;,:]/g,'\\$&')+';H:'+(hidden.value?'true':'false')+';;'; const generate=async()=>{image.value=ssid.value.trim()?await QRCode.toDataURL(payload(),{margin:2,width:300}):''}; watch([ssid,password,security,hidden],()=>{clearTimeout(timer);timer=window.setTimeout(()=>void generate(),100)}); const download=()=>{if(!image.value)return;const a=document.createElement('a');a.href=image.value;a.download='pqt-forge-wifi.png';a.click()}
</script>
<style scoped>.wifi-panel{display:grid;gap:12px}.wifi-panel label{display:grid;gap:6px;color:var(--pqt-text-muted);font-size:11px}.wifi-panel input,.wifi-panel select{padding:9px 10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.wifi-preview{display:grid;place-items:center;width:230px;height:230px;padding:10px;background:#fff;border-radius:8px;color:#667}.wifi-preview img{max-width:100%;max-height:100%}</style>
